from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import json
import math
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

import boundaryguard_scale_gate as base


ROOT = _GITHUB_ROOT
OUT = DATA / "boundaryguard_scale_four_chain.jsonl"
SUMMARY = DATA / "boundaryguard_scale_four_chain_summary.json"
PRIOR = DATA / "boundaryguard_scale_normal_600.jsonl"
TARGET_VALID_PER_CHAIN = 250
BATCH_WIDTH = 200
LOCK = threading.Lock()

CONFIG = {
    "optimism": base.CONFIG["optimism"],
    "polygon": base.CONFIG["polygon"],
    "ethereum": {
        "primary_name": "zeroxrpc",
        "primary_url": "https://0xrpc.io/eth",
        "primary_fallbacks": [
            "https://eth.llamarpc.com",
            "https://ethereum-rpc.publicnode.com",
        ],
        "boundary_name": "drpc",
        "boundary_url": "https://eth.drpc.org",
        "repair_name": "llamarpc",
        "repair_url": "https://eth.llamarpc.com",
    },
    "arbitrum": {
        "primary_name": "official",
        "primary_url": "https://arb1.arbitrum.io/rpc",
        "primary_fallbacks": [
            "https://arbitrum-one.public.blastapi.io",
            "https://arb-pokt.nodies.app",
            "https://arbitrum.drpc.org",
        ],
        # Free tip RPCs lack deep historical eth_call; use archive-capable boundaries.
        "boundary_name": "blast",
        "boundary_url": "https://arbitrum-one.public.blastapi.io",
        "boundary_fallbacks": [
            "https://arbitrum.gateway.tenderly.co",
            "https://arb-pokt.nodies.app",
        ],
        "repair_name": "nodies",
        "repair_url": "https://arb-pokt.nodies.app",
    },
}


def normalize(value: str) -> str:
    return "0x" + value.removeprefix("\\x").removeprefix("0x").lower()


def load_prior() -> list[dict]:
    rows = []
    if PRIOR.exists():
        with PRIOR.open() as handle:
            for line in handle:
                row = json.loads(line)
                row.setdefault("provenance", "live_natural_observation")
                rows.append(row)
    if OUT.exists():
        with OUT.open() as handle:
            for line in handle:
                rows.append(json.loads(line))
    # de-dup by chain/start/end keeping latest
    keyed = {}
    for row in rows:
        keyed[(row["chain"], row["start"], row["end"])] = row
    return list(keyed.values())


def load_messages() -> dict[str, list[dict]]:
    grouped = {chain: [] for chain in CONFIG}
    with base.MESSAGES.open() as handle:
        for line in handle:
            row = json.loads(line)
            if row["chain"] in grouped:
                grouped[row["chain"]].append(row)
    for rows in grouped.values():
        rows.sort(key=lambda row: row["origin_block_height"])
    return grouped


def density_bins(rows: list[dict], start: int, end: int) -> str:
    count = sum(1 for row in rows if start <= row["origin_block_height"] <= end)
    if count <= 0:
        return "low"
    if count == 1:
        return "medium"
    return "high"


def overlaps(start: int, occupied: list[tuple[int, int]]) -> bool:
    end = start + BATCH_WIDTH - 1
    return any(not (end < left or start > right) for left, right in occupied)


def tip_intervals(url: str, need: int, occupied: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Sample non-overlapping finalized ranges walking backward from tip."""
    tip_resp = base.rpc_retry(url, "eth_blockNumber", [])
    if tip_resp["outcome"] != "ok" or not isinstance(tip_resp.get("result"), str):
        raise RuntimeError(f"cannot read tip from {url}")
    tip = int(tip_resp["result"], 16)
    # stay well below tip for finality
    cursor = tip - 128
    selected: list[tuple[int, int]] = []
    guard = 0
    while len(selected) < need and cursor > BATCH_WIDTH + 10 and guard < need * 20:
        guard += 1
        end = cursor
        start = end - BATCH_WIDTH + 1
        if not overlaps(start, occupied + selected):
            selected.append((start, end))
        cursor = start - BATCH_WIDTH  # non-overlapping stride
    if len(selected) < need:
        raise RuntimeError(f"tip sampling only selected {len(selected)} intervals, need {need}")
    return list(reversed(selected))


def choose_intervals(rows: list[dict], occupied: list[tuple[int, int]], need: int,
                     tip_url: str | None = None) -> list[tuple[int, int]]:
    lo = rows[0]["origin_block_height"] + 1
    hi = rows[-1]["origin_block_height"] - BATCH_WIDTH - 1
    span = max(0, hi - lo)
    max_fit = max(0, span // BATCH_WIDTH)
    if need > max_fit:
        if not tip_url:
            raise RuntimeError(f"need {need} intervals but message span fits ~{max_fit}")
        return tip_intervals(tip_url, need, occupied)
    selected: list[tuple[int, int]] = []
    for index in range(1, 40001):
        start = round(lo + index * (hi - lo) / 40002)
        if overlaps(start, occupied + selected):
            continue
        selected.append((start, start + BATCH_WIDTH - 1))
        if len(selected) >= need:
            break
    if len(selected) < need:
        raise RuntimeError(f"only selected {len(selected)} intervals, need {need}")
    return selected


def append(record: dict) -> None:
    with LOCK:
        with OUT.open("a") as handle:
            handle.write(json.dumps(record, sort_keys=True) + "\n")
            handle.flush()


def get_logs_with_fallback(cfg: dict, mailbox: str, start: int, end: int) -> dict:
    urls = [cfg["primary_url"], *cfg.get("primary_fallbacks", [])]
    last = None
    for url in urls:
        last = base.rpc_retry(
            url,
            "eth_getLogs",
            [{"fromBlock": hex(start), "toBlock": hex(end), "address": mailbox,
              "topics": [base.DISPATCH_TOPIC]}],
            attempts=2,
        )
        if last["outcome"] == "ok" and isinstance(last.get("result"), list):
            last["used_url"] = url
            return last
    assert last is not None
    last["used_url"] = urls[-1]
    return last


def read_nonce_with_fallback(cfg: dict, mailbox: str, block: int) -> dict:
    urls = [cfg["boundary_url"], *cfg.get("boundary_fallbacks", [])]
    last = None
    for url in urls:
        last = base.read_nonce(url, mailbox, block)
        if last.get("value") is not None:
            last["used_url"] = url
            return last
    assert last is not None
    last["used_url"] = urls[-1]
    return last


def run_new_batches(chain: str, rows: list[dict], intervals: list[tuple[int, int]], done: set[tuple]) -> None:
    cfg = CONFIG[chain]
    mailbox = normalize(rows[0]["origin_mailbox"])
    for index, (start, end) in enumerate(intervals):
        if (chain, start, end) in done:
            continue
        wall_started = time.perf_counter()
        before = read_nonce_with_fallback(cfg, mailbox, start - 1)
        after = read_nonce_with_fallback(cfg, mailbox, end)
        primary = get_logs_with_fallback(cfg, mailbox, start, end)
        logs = primary.pop("result", None)
        returned = len(logs) if isinstance(logs, list) else None
        expected = None if before["value"] is None or after["value"] is None else after["value"] - before["value"]
        valid = expected is not None and returned is not None
        record = {
            "provenance": "live_natural_observation",
            "ts": time.time(),
            "chain": chain,
            "batch_index": index,
            "start": start,
            "end": end,
            "width": BATCH_WIDTH,
            "density_bin": density_bins(rows, start, end),
            "mailbox": mailbox,
            "primary": cfg["primary_name"],
            "primary_url_used": primary.get("used_url"),
            "boundary": cfg["boundary_name"],
            "repair": cfg["repair_name"],
            "nonce_before": before["value"],
            "nonce_after": after["value"],
            "expected_dispatches": expected,
            "returned_dispatches": returned,
            "valid": valid,
            "alarm": valid and expected != returned,
            "wall_ms": round((time.perf_counter() - wall_started) * 1000, 3),
            "primary_outcome": primary["outcome"],
            "primary_latency_ms": primary["latency_ms"],
            "primary_attempts": primary["attempts"],
            "boundary_before_outcome": before["outcome"],
            "boundary_before_attempts": before["attempts"],
            "boundary_before_latency_ms": before["latency_ms"],
            "boundary_after_outcome": after["outcome"],
            "boundary_after_attempts": after["attempts"],
            "boundary_after_latency_ms": after["latency_ms"],
        }
        append(record)
        print(chain, index + 1, "/", len(intervals), "valid", valid, "alarm", record["alarm"],
              "density", record["density_bin"], "primary", primary.get("used_url"), flush=True)
        time.sleep(0.02)


def live_density_bin(expected: int | None) -> str:
    """Density from the audited nonce delta (live), not the frozen catalog."""
    if expected is None or expected <= 0:
        return "empty"
    if expected == 1:
        return "low"
    if expected <= 4:
        return "medium"
    return "high"


def summarize(records: list[dict]) -> dict:
    out = {"chains": {}, "overall": {}}
    alarms = 0
    valid_total = 0
    valid_nonempty = 0
    nonempty_alarms = 0
    for chain in CONFIG:
        rows = [row for row in records if row["chain"] == chain]
        valid = [row for row in rows if row["valid"]]
        nonempty = [row for row in valid if (row.get("expected_dispatches") or 0) > 0]
        chain_alarms = sum(bool(row["alarm"]) for row in valid)
        chain_nonempty_alarms = sum(bool(row["alarm"]) for row in nonempty)
        alarms += chain_alarms
        nonempty_alarms += chain_nonempty_alarms
        valid_total += len(valid)
        valid_nonempty += len(nonempty)
        dens = {}
        for bin_name in ("empty", "low", "medium", "high"):
            subset = [
                row for row in valid
                if live_density_bin(row.get("expected_dispatches")) == bin_name
            ]
            dens[bin_name] = {
                "valid": len(subset),
                "alarms": sum(bool(row["alarm"]) for row in subset),
            }
        catalog_dens = {}
        for bin_name in ("low", "medium", "high"):
            subset = [row for row in valid if row.get("density_bin") == bin_name]
            catalog_dens[bin_name] = {
                "valid": len(subset),
                "alarms": sum(bool(row["alarm"]) for row in subset),
            }
        out["chains"][chain] = {
            "batches": len(rows),
            "valid_batches": len(valid),
            "valid_nonempty_batches": len(nonempty),
            "alarms": chain_alarms,
            "nonempty_alarms": chain_nonempty_alarms,
            "false_alarm_rate": (chain_alarms / len(valid)) if valid else None,
            "nonempty_false_alarm_rate": (chain_nonempty_alarms / len(nonempty)) if nonempty else None,
            "density_by_expected": dens,
            "density_by_catalog": catalog_dens,
            "primary": CONFIG[chain]["primary_name"],
            "boundary": CONFIG[chain]["boundary_name"],
            "repair": CONFIG[chain]["repair_name"],
        }
    out["overall"] = {
        "batches": len(records),
        "valid_batches": valid_total,
        "valid_nonempty_batches": valid_nonempty,
        "alarms": alarms,
        "nonempty_alarms": nonempty_alarms,
        "false_alarm_rate": (alarms / valid_total) if valid_total else None,
        "nonempty_false_alarm_rate": (nonempty_alarms / valid_nonempty) if valid_nonempty else None,
        "chains": len(CONFIG),
        "target_valid_per_chain": TARGET_VALID_PER_CHAIN,
        "meets_1000_valid": valid_total >= 1000,
        "meets_4_chains": all(out["chains"][c]["valid_batches"] >= TARGET_VALID_PER_CHAIN for c in CONFIG),
    }
    if alarms == 0 and valid_total > 0:
        out["overall"]["zero_alarm_exact_one_sided_95pct_upper"] = 1 - math.pow(0.05, 1 / valid_total)
    if nonempty_alarms == 0 and valid_nonempty > 0:
        out["overall"]["nonempty_zero_alarm_exact_one_sided_95pct_upper"] = (
            1 - math.pow(0.05, 1 / valid_nonempty)
        )
    return out


def run_chain_parallel(chain: str, rows: list[dict], intervals: list[tuple[int, int]], done: set[tuple], workers: int = 6) -> None:
    if not intervals:
        return
    shard = max(1, (len(intervals) + workers - 1) // workers)
    parts = [intervals[i:i + shard] for i in range(0, len(intervals), shard)]
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futs = [pool.submit(run_new_batches, chain, rows, part, done) for part in parts]
        for fut in futs:
            fut.result()


def main() -> None:
    prior = load_prior()
    grouped = load_messages()
    # Import prior OP/Polygon into OUT if missing eth/arb-only file.
    if not OUT.exists() and PRIOR.exists():
        with OUT.open("w") as handle:
            for row in prior:
                if row["chain"] in ("optimism", "polygon"):
                    handle.write(json.dumps(row, sort_keys=True) + "\n")
        prior = load_prior()
    done = {(row["chain"], row["start"], row["end"]) for row in prior}
    planned = {}
    for chain, rows in grouped.items():
        have = sum(1 for row in prior if row["chain"] == chain and row.get("valid"))
        need = max(0, TARGET_VALID_PER_CHAIN - have + 20)  # small buffer for unavailable
        occupied = [(row["start"], row["end"]) for row in prior if row["chain"] == chain]
        planned[chain] = choose_intervals(
            rows,
            occupied,
            need,
            tip_url=CONFIG[chain]["primary_url"],
        ) if need else []
        print(chain, "have_valid", have, "plan_new", len(planned[chain]), flush=True)
    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = [
            pool.submit(run_chain_parallel, chain, grouped[chain], intervals, done, 6)
            for chain, intervals in planned.items() if intervals
        ]
        for future in futures:
            future.result()
    records = load_prior()
    # rewrite OUT as canonical combined four-chain set
    with OUT.open("w") as handle:
        for row in sorted(records, key=lambda r: (r["chain"], r["start"])):
            if row["chain"] in CONFIG:
                handle.write(json.dumps(row, sort_keys=True) + "\n")
    summary = summarize([row for row in records if row["chain"] in CONFIG])
    SUMMARY.write_text(json.dumps(summary, indent=2, sort_keys=True) + "\n")
    print(json.dumps(summary, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
